<div class="intro-line"><p>Permintaan dicatat sebagai tiket dengan penanggung jawab, status, dan riwayat yang dapat ditelusuri.</p><?php if ($can_create): ?><a class="button button-dark" href="<?= site_url('admin/kasus/'.$slug.'/tambah') ?>">+ Buat tiket</a><?php endif; ?></div>
<?php if ($slug==='layanan'): ?><div class="note-strip">Permohonan izin KSP/USP diproses melalui kanal resmi <a href="https://oss.go.id/" target="_blank" rel="noopener noreferrer">OSS ↗</a>. Tiket di sini mencatat pendampingan dan pemeriksaan kelengkapan, bukan menerbitkan izin.</div><?php endif; ?>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari tiket</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nomor, judul, koperasi"></label><label><span>Status</span><select name="status"><option value="">Semua</option><?php foreach ($statuses as $code=>$name): ?><option value="<?= h($code) ?>" <?= $p['status']===$code?'selected':'' ?>><?= h($name) ?></option><?php endforeach; ?></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Nomor tiket</th><th>Perihal</th><th>Koperasi</th><th>Status</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td class="mono"><?= h($r['ticket_no']) ?></td><td><strong><?= h($r['title']) ?></strong><small class="cell-sub"><?= h($r['assignee_name']?:'Belum ditugaskan') ?></small></td><td><?= h($r['cooperative_name']?:'—') ?></td><td><span class="pill <?= $r['status']==='closed'?'pill-green':'pill-blue' ?>"><?= h($statuses[$r['status']]??$r['status']) ?></span></td><td><?= h(date('d M Y',strtotime($r['created_at']))) ?></td><td><a class="row-link" href="<?= site_url('admin/kasus/'.$slug.'/'.$r['id']) ?>">Buka →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6" class="empty-cell">Tidak ada tiket yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
